class Spell {
  constructor(name) {
    this.name = name;
  }

  cast() {
    // This conditional check for the constructor name is an unnecessary abstraction.
    // For an abstract method, the intention is always to throw if not overridden,
    // regardless of whether the call originates from the base class or an unimplemented subclass.
    // A direct throw statement is simpler, more efficient, and standard practice.
    if (this.constructor.name === 'Spell') {
      throw new Error("Method 'cast()' must be implemented by subclasses.");
    } else {
      throw new Error(`Method 'cast()' of ${this.constructor.name} must be implemented.`);
    }
  }

  getName() {
    return this.name;
  }
}

class FireballSpell extends Spell {
  constructor() {
    super("Fireball");
  }

  cast() {
    return `Casting ${this.name}: A fiery projectile erupts!`;
  }
}

class HealSpell extends Spell {
  constructor() {
    super("Heal");
  }

  cast() {
    return `Casting ${this.name}: Gentle light mends wounds.`;
  }
}

// Test Cases
const fireball = new FireballSpell();
console.log(fireball.cast());

const heal = new HealSpell();
console.log(heal.cast());

// This should demonstrate the abstract nature of Spell
try {
  const genericSpell = new Spell("Unknown");
  genericSpell.cast();
} catch (e) {
  console.log(e.message);
}

